package com.vocal.service;
import com.vocal.dto.CommerceDtos.*; import com.vocal.entity.*; import com.vocal.enums.OrderStatus; import com.vocal.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*; import java.security.Principal; import java.util.UUID;
@Service @RequiredArgsConstructor public class CheckoutService { private final UserRepository users; private final CartItemRepository carts; private final OrderRepository orders; private final CartService cartService; @Transactional public OrderResponse checkout(CheckoutRequest req, Principal p){User u=users.findByEmail(p.getName()).orElseThrow(); var lines=cartService.list(p); BigDecimal subtotal=lines.stream().map(l->l.unitPrice().multiply(BigDecimal.valueOf(l.quantity()))).reduce(BigDecimal.ZERO,BigDecimal::add); BigDecimal tax=subtotal.multiply(new BigDecimal("0.18")).setScale(2,RoundingMode.HALF_UP); BigDecimal shipping=subtotal.compareTo(new BigDecimal("2999"))>=0?BigDecimal.ZERO:new BigDecimal("99.00"); Order o=Order.builder().orderNumber("VOC-"+UUID.randomUUID().toString().substring(0,8).toUpperCase()).user(u).status(OrderStatus.PLACED).subtotal(subtotal).tax(tax).shipping(shipping).total(subtotal.add(tax).add(shipping)).build(); orders.save(o); carts.findByUserId(u.getId()).forEach(carts::delete); return new OrderResponse(o.getId(),o.getOrderNumber(),o.getStatus().name(),o.getSubtotal(),o.getTax(),o.getShipping(),o.getTotal(),lines);} }
